next.template:
PREFIX schema: <https://schema.org/>
PREFIX seeds: <https://seeds.local/ontology/>
PREFIX q: <https://scbrown.github.io/quechua/ns#>
PREFIX ical: <http://www.w3.org/2002/12/cal/ical#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?item ?id ?title ?priority ?rank ?status ?owner ?due ?revision ?modified ?sourceKind ?confidence WHERE { GRAPH <https://example.test/project/demo> { ?item a schema:Action ; schema:identifier ?id ; schema:name ?title ;
 seeds:priority ?priority ; seeds:status ?status ; schema:version ?revision ;
 schema:dateModified ?modified .
 OPTIONAL { ?item seeds:rank ?rank }
 OPTIONAL { ?item schema:agent ?owner }
 OPTIONAL { ?item ical:due ?due }
 OPTIONAL { ?item q:sourceKind ?sourceKind }
 OPTIONAL { ?item q:confidence ?confidence }
 BIND(COALESCE(?rank, 1000000000) AS ?sortRank)
 FILTER(?status != "closed" && ?status != "tombstone")
FILTER NOT EXISTS { ?item schema:keywords "inbox" } } } ORDER BY ?priority ?sortRank ?id LIMIT 40

asks.template:
