closes.template:
PREFIX schema: <https://schema.org/>
PREFIX seeds: <https://seeds.local/ontology/>
PREFIX q: <https://scbrown.github.io/quechua/ns#>
PREFIX ical: <http://www.w3.org/2002/12/cal/ical#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?item ?id ?title ?revision ?modified ?closed ?reason ?sourceKind WHERE { GRAPH <https://example.test/project/demo> {
 ?item a schema:Action ; schema:identifier ?id ; schema:name ?title ; seeds:status "closed" ;
 schema:version ?revision ; schema:dateModified ?modified ; schema:endTime ?closed .
 FILTER(xsd:dateTime(?closed) >= xsd:dateTime('{start}') && xsd:dateTime(?closed) < xsd:dateTime('{end}'))
 OPTIONAL { ?item q:closeReason ?reason } OPTIONAL { ?item q:sourceKind ?sourceKind }
 FILTER NOT EXISTS { ?item schema:keywords "inbox" }
 } } ORDER BY DESC(?closed) ?id LIMIT 501
